    },
    {
      "name": "overpressure_trip",
      "value": "20.00",
      "units": "kPa(g)",
      "narrative_section": "4.8"
    },
    {
      "name": "pt_fault_below",
      "value": "-5.00",
      "units": "kPa(g)",
      "narrative_section": "4.8"
    },
    {
      "name": "cycle_time_budget",
      "value": "23.0",
      "units": "s",
      "narrative_section": "4.8"
    }
  ],
  "steps": [
    {
      "name": "IDLE",
      "entry": "Initial state or pallet leaves ST20 (falling edge of ZS-2008 / ANI X23 while in DONE M207)",
      "exit": "Pallet arrival (LDP X23) with Auto mode (X2), not busy (ANI M200), and no ST20 fault (ANI M299)"
    },
    {
      "name": "CLAMP (M201)",
      "entry": "Start conditions met from IDLE",
      "exit": "Clamp confirmed closed (ZS-2002A / X20) and open switch clear (ANI ZS-2002B / X21)"
    },
    {
      "name": "FILL (M202)",
      "entry": "Clamp confirmed closed from CLAMP step",
      "exit": "PT-2001 reaches fill threshold (D100 >= D122 / 14.50 kPa) OR fill timeout (T21) / fault condition aborts to VENT"
    },
    {
      "name": "STABILISE (M203)",
      "entry": "PT-2001 >= fill threshold (14.50 kPa)",
      "exit": "Stabilisation timer done (T22)"
    },
    {
      "name": "TEST (M204)",
      "entry": "Stabilisation timer done (T22)",
      "exit": "Test window timer done (T23)"
    },
    {
      "name": "VENT (M205)",
      "entry": "Test window complete (T23) OR cycle aborted due to fault / E-stop (M299)",
      "exit": "Vent timer done (T24 / T200), pressure vented below 1.00 kPa (D100 < K100), and PT-2001 healthy (ANI M292)"
    },
    {
      "name": "UNCLAMP (M206)",
      "entry": "Vent conditions satisfied (pressure < 1.00 kPa, vent timer done, PT healthy)",
      "exit": "Clamp confirmed open (ZS-2002B / X21 made and ZS-2002A / X20 clear)"
    },
    {
      "name": "DONE (M207)",
      "entry": "Clamp confirmed open from UNCLAMP step",
      "exit": "Pallet leaves test position (falling edge/clear of ZS-2008 / X23)"
    }
  ],
  "interlocks": [
    {
      "cause": "Cell not in auto mode (X2), ST20 fault active (M299), or station busy (M200)",
      "effect": "Inhibit start of test cycle"
    },
    {
      "cause": "Clamp not confirmed closed (ZS-2002A / X20 false or ZS-2002B / X21 true)",
      "effect": "Inhibit transition to FILL and close fill valve XV-2003 (Y21)"
    },
    {
      "cause": "Fault active (M299) while ST20 is busy (M200)",
      "effect": "Abort sequence immediately to VENT (M205) and latch FAIL (M211)"
    },
    {
      "cause": "Pressure >= 1.00 kPa (D100 >= K100) or PT-2001 fault active (M292) during VENT",
      "effect": "Inhibit transition from VENT (M205) to UNCLAMP (M206), holding vent valve open and clamp closed"
    },
    {
      "cause": "Manual vent PB-2010 (X25) pressed while not in auto mode (ANI X2)",
      "effect": "Energise vent valve XV-2004 (Y22)"
    },
    {
      "cause": "Overpressure detected (PT-2001 > 20.00 kPa / M291)",
      "effect": "Energise vent valve XV-2004 (Y22) to depressurise pack"
    }
  ],
  "alarms": [
    {
      "name": "Fill timeout (M290)",
      "condition": "Test fill pressure not reached within fill timeout period (T21 done while in FILL M202)",
      "action": "Abort cycle to VENT (M205), set FAIL result (M211), light ST20 fault beacon HL-2011 (Y25)"
    },
    {
      "name": "Over-pressure trip (M291)",
      "condition": "Pack pressure PT-2001 exceeds overpressure threshold D123 (20.00 kPa)",
      "action": "Latched trip, close fill valve, force vent valve XV-2004 (Y22) open, abort cycle to VENT with FAIL, light beacon HL-2011 (Y25)"
    },
    {
      "name": "PT-2001 signal fault (M292)",
      "condition": "Pack pressure PT-2001 reading below -5.00 kPa (D100 < K-500, indicating wire break)",
      "action": "Inhibit cycle start, inhibit unclamp transition from VENT, light beacon HL-2011 (Y25)"
    },
    {
      "name": "Supply air low (M293)",
      "condition": "Supply air pressure switch PS-2009 (X22) lost while ST20 is busy (M200)",
      "action": "Latched alarm, abort cycle to VENT (M205), set FAIL result (M211), light beacon HL-2011 (Y25)"
    },
    {
      "name": "E-stop chain open (X0)",
      "condition": "E-stop healthy contact ES-0001 (X0) drops",
      "action": "Sets fault summary M299, aborts cycle to VENT with FAIL, lights beacon HL-2011 (Y25)"
    }
  ],
  "conflicts": [
    {
      "item": "stabilise_time",
      "narrative_says": "3 s (section 4.4)",
      "parameter_sheet_says": "5.0 s (T22, changed from 3.0 s by MOC-2021-044)",
      "program_says": "5.0 s (OUT T22 K50 in R13, 100 ms timer = 5.0 s)",
      "authoritative": "parameter_sheet"
    },
    {
      "item": "vent_time",
      "narrative_says": "0.5 s (section 4.7)",
      "parameter_sheet_says": "0.5 s (T24)",
      "program_says": "5.0 s (OUT T200 K50 in R21; on FX5 OUT is 100 ms base making K50 = 5.0 s, converting FX3 10 ms timer T200 incorrectly)",
      "authoritative": "parameter_sheet"
    },
    {
      "item": "test_pressure",
      "narrative_says": "15.00 kPa(g) in title/text, regulator PR-2012 set to 15.2 kPa in section 4.3",
      "parameter_sheet_says": "15.00 kPa(g) (note: supply regulator PR-2012 set to 15.2 kPa)",
      "program_says": "Not directly referenced in program (mechanical regulator PR-2012)",
      "authoritative": "parameter_sheet"
    }
  ]
}
